CREATE COLUMN TABLE "TEST_AP"."WOR4" ("DocEntry" INTEGER CS_INT NOT NULL , "StageId" INTEGER CS_INT NOT NULL , "SeqNum" INTEGER CS_INT NOT NULL , "StgEntry" INTEGER CS_INT, "Name" NVARCHAR(100), "LogInstanc" INTEGER CS_INT DEFAULT 0, "StartDate" LONGDATE CS_LONGDATE, "EndDate" LONGDATE CS_LONGDATE, "Status" NVARCHAR(1) DEFAULT 'P', "RtCalcProp" DECIMAL(21,6) CS_FIXED DEFAULT 100, "ReqDays" DECIMAL(21,6) CS_FIXED DEFAULT 0, "WaitDays" DECIMAL(21,6) CS_FIXED DEFAULT 0, PRIMARY KEY ("DocEntry", "StageId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "WOR4_SEQUENCE" ON "TEST_AP"."WOR4" ( "DocEntry" ASC, "SeqNum" ASC )